int wext_get_ssid(const char *ifname, __u8 *ssid)
{
	struct iwreq iwr;
	int ret = 0;
	static int last_connected = 0;  /* 0 = not connected, 1 = connected */

	memset(&iwr, 0, sizeof(iwr));
	iwr.u.essid.pointer = ssid;
	iwr.u.essid.length = 32;

	if (iw_ioctl(ifname, SIOCGIWESSID, &iwr) < 0) {
		if (last_connected == 1) {
			DBG_INFO("ioctl[SIOCGIWESSID] disconnected");  /* 状态变化：连接→断开 */
		}
		last_connected = 0;
		ret = -1;
	} else {
		ret = iwr.u.essid.length;
		if (ret > 32)
			ret = 32;
		if (ret > 0 && ssid[ret - 1] == '\0')
			ret--;
		ssid[ret] = '\0';
		if (last_connected == 0) {
			DBG_INFO("ioctl[SIOCGIWESSID] connected, ssid = %s", ssid);  /* 状态变化：断开→连接 */
		}
		last_connected = 1;
	}
	return ret;
}
```

