int wext_get_ssid(const char *ifname, __u8 *ssid)
{
	struct iwreq iwr;
	int ret = 0;
	static int last_connected = -1; /* -1: 初始, 0: 未连接, 1: 已连接; 只在状态翻转时打日志 */

	memset(&iwr, 0, sizeof(iwr));
	iwr.u.essid.pointer = ssid;
	iwr.u.essid.length = 32;

	if (iw_ioctl(ifname, SIOCGIWESSID, &iwr) < 0) {
		if (last_connected != 0) {
			DBG_INFO("ioctl[SIOCGIWESSID] ssid = NULL, not connected"); //do not use perror
			last_connected = 0;
		}
		ret = -1;
	} else {
		ret = iwr.u.essid.length;
		if (ret > 32)
			ret = 32;
		/* Some drivers include nul termination in the SSID, so let's
		 * remove it here before further processing. WE-21 changes this
		 * to explicitly require the length _not_ to include nul
		 * termination. */
		if (ret > 0 && ssid[ret - 1] == '\0')
			ret--;
		ssid[ret] = '\0';
		if (last_connected != 1) {
			DBG_INFO("ioctl[SIOCGIWESSID] connected, ssid = %s", ssid);
			last_connected = 1;
		}
	}
	return ret;
}

